def is_multiply_prime(a):
    """Check if a number can be expressed as the product of exactly three prime numbers."""
    if a < 3:
        return False

    def is_prime(n):
        """Check if a number is prime."""
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Generate all primes up to a
    primes = []
    for i in range(2, a + 1):
        if is_prime(i):
            primes.append(i)

    # Check all possible triplets of primes
    for p1 in primes:
        if a % p1 != 0:
            continue
        remaining = a // p1
        for p2 in primes:
            if p2 < p1:
                continue
            if remaining % p2 != 0:
                continue
            remaining_after_p2 = remaining // p2
            if is_prime(remaining_after_p2):
                return True

    return False

