import math

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_div = int(math.sqrt(n)) + 1
    for i in range(3, max_div, 2):
        if n % i == 0:
            return False
    return True

def newman_prime(n):
    primes = []
    k = 1
    while len(primes) < n:
        num = k * k - 2
        if is_prime(num):
            primes.append(num)
        k += 1
    return primes[n - 1]

# Test the function
assert newman_prime(3) == 7

