def max_aggregate(tuples):
    name_to_sum = {}
    for name, score in tuples:
        if name in name_to_sum:
            name_to_sum[name] += score
        else:
            name_to_sum[name] = score
    max_key = max(name_to_sum, key=lambda x: name_to_sum[x])
    return (max_key, name_to_sum[max_key])
